// ============================================================
// TEST DATA — Simulates a webhook call with client_code
// In production this comes from the webhook payload.
// ============================================================

return [{
  json: {
    body: {
      client_code: 'TES-0213'
    }
  }
}];

// ============================================================
// Extract client_code from webhook or test payload
// ============================================================

const body = $input.first().json.body || $input.first().json;
const client_code = (body.client_code || body.clientCode || '').trim();

if (!client_code) {
  throw new Error('client_code is required in the webhook payload');
}

return [{
  json: {
    client_code,
    scripts_folder_id: body.scripts_folder_id || '',
    clickup_list_id: body.clickup_list_id || ''
  }
}];

// ============================================================
// Validate Brief & Merge Context
// Ensures all required fields are present and builds
// a clean data object for downstream AI prompts.
// ============================================================

const items = $input.all();
if (!items || items.length === 0 || !items[0].json) {
  throw new Error('No client found for the given client_code. Check the Client Database sheet.');
}

const row = items[0].json;

// Passthrough optional IDs from the trigger
let scripts_folder_id = '';
let clickup_list_id = '';
try {
  const trigger = $('Extract Client Code').first().json;
  scripts_folder_id = trigger.scripts_folder_id || '';
  clickup_list_id = trigger.clickup_list_id || '';
} catch(e) {}

function clean(val) {
  if (val === undefined || val === null) return '';
  return String(val).trim();
}

const brief = {
  client_code: clean(row.client_code),
  brand_name: clean(row.brand_name),
  client_name: clean(row.client_name),
  client_email: clean(row.client_email),
  whatsapp_number: clean(row.whatsapp_number),
  website_url: clean(row.website_url),
  product_feature: clean(row.product_feature),
  differentiator: clean(row.differentiator),
  competitors: clean(row.competitors),
  competitor_strengths: clean(row.competitor_strengths),
  target_user: clean(row.target_user),
  biggest_problem: clean(row.biggest_problem),
  main_hesitation: clean(row.main_hesitation),
  social_proof: clean(row.social_proof),
  selling_proposition: clean(row.selling_proposition),
  brand_personality: clean(row.brand_personality),
  credibility_point: clean(row.credibility_point),
  transformation: clean(row.transformation),
  best_concepts: clean(row.best_concepts),
  compliance: clean(row.compliance),
  reference_ads: clean(row.reference_ads),
  available_assets: clean(row.available_assets),
  do_not_say: clean(row.do_not_say),
  additional_notes: clean(row.additional_notes),
  num_scripts: parseInt(clean(row.num_scripts)) || 3,
  scripts_folder_id,
  clickup_list_id
};

// Validation
const required = ['brand_name', 'product_feature', 'target_user'];
const missing = required.filter(f => !brief[f]);
if (missing.length > 0) {
  throw new Error('Brief is missing required fields: ' + missing.join(', '));
}

return [{ json: brief }];

