// ============================================================
// Parse AI Strategy Response
// Extracts creative angles from OpenAI JSON response
// ============================================================

const response = $input.first().json;

if (!response.choices || !response.choices[0]) {
  throw new Error('No response from AI strategy call. Check API key and model.');
}

const content = response.choices[0].message.content;
let strategy;
try {
  strategy = JSON.parse(content);
} catch (e) {
  // Try extracting JSON from markdown code block
  const match = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) {
    strategy = JSON.parse(match[1]);
  } else {
    throw new Error('Failed to parse AI strategy response: ' + content.substring(0, 200));
  }
}

if (!strategy.angles || !Array.isArray(strategy.angles)) {
  throw new Error('AI response missing angles array');
}

// Get brief data for next step
const brief = $('Validate & Prepare Brief').first().json;

return [{
  json: {
    brief,
    strategy
  }
}];

