// ============================================================
// Parse AI Scripts Response
// Extracts all generated scripts from OpenAI response.
// Formats each script as a readable document for Google Docs.
// ============================================================

const response = $input.first().json;

if (!response.choices || !response.choices[0]) {
  throw new Error('No response from AI script writing call.');
}

const content = response.choices[0].message.content;
let result;
try {
  result = JSON.parse(content);
} catch (e) {
  const match = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) {
    result = JSON.parse(match[1]);
  } else {
    throw new Error('Failed to parse AI scripts response: ' + content.substring(0, 300));
  }
}

if (!result.scripts || !Array.isArray(result.scripts)) {
  throw new Error('AI response missing scripts array');
}

const brief = $('Validate & Prepare Brief').first().json;
const strategy = $('Parse Creative Strategy').first().json.strategy;

// Format each script as a readable document
const formattedScripts = result.scripts.map((s, i) => {
  const onScreenText = Array.isArray(s.on_screen_text) 
    ? s.on_screen_text.map(t => `  • ${t}`).join('\n') 
    : s.on_screen_text || '';

  const docContent = [
    `${brief.brand_name} — UGC Script #${s.script_number || (i+1)}`,
    `═══════════════════════════════════════════`,
    ``,
    `ANGLE: ${s.angle_name}`,
    `FORMAT: ${s.format}`,
    `DURATION: ${s.estimated_duration || '30 sec'}`,
    ``,
    `───────────────────────────────────────────`,
    `HOOK (0-3 sec)`,
    `───────────────────────────────────────────`,
    s.hook,
    ``,
    `───────────────────────────────────────────`,
    `PROBLEM (3-8 sec)`,
    `───────────────────────────────────────────`,
    s.problem,
    ``,
    `───────────────────────────────────────────`,
    `SOLUTION (8-18 sec)`,
    `───────────────────────────────────────────`,
    s.solution,
    ``,
    `───────────────────────────────────────────`,
    `PROOF (18-25 sec)`,
    `───────────────────────────────────────────`,
    s.proof,
    ``,
    `───────────────────────────────────────────`,
    `CTA (25-30 sec)`,
    `───────────────────────────────────────────`,
    s.cta,
    ``,
    `═══════════════════════════════════════════`,
    `FULL SCRIPT (for creator to read)`,
    `═══════════════════════════════════════════`,
    s.full_script,
    ``,
    `═══════════════════════════════════════════`,
    `VISUAL DIRECTION`,
    `═══════════════════════════════════════════`,
    s.visual_direction,
    ``,
    `ON-SCREEN TEXT:`,
    onScreenText,
    ``,
    `CREATOR NOTES:`,
    s.creator_notes,
    ``,
    `───────────────────────────────────────────`,
    `Generated by Smashed Agency Script Agent`,
    `Client Code: ${brief.client_code}`,
    `Generated: ${new Date().toISOString()}`
  ].join('\n');

  return {
    script_number: s.script_number || (i + 1),
    angle_name: s.angle_name,
    format: s.format,
    hook: s.hook,
    full_script: s.full_script,
    doc_content: docContent,
    estimated_duration: s.estimated_duration || '30 sec'
  };
});

return [{
  json: {
    brief,
    strategy,
    scripts: formattedScripts,
    total_scripts: formattedScripts.length
  }
}];

// ============================================================
// Match Scripts to Google Docs
// Pairs each AI-generated script with its corresponding
// Google Doc based on the naming convention:
// UGC_C{N}_{Brand}_Creator Name_R1_{Mon'YY}
// ============================================================

const data = $('Parse & Format Scripts').first().json;
const driveResult = $input.first().json;
const docs = driveResult.files || [];

const scripts = data.scripts;
const brief = data.brief;

// Sort docs by name to match script numbers
const sortedDocs = docs.sort((a, b) => {
  const numA = parseInt((a.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  const numB = parseInt((b.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  return numA - numB;
});

const items = [];
for (let i = 0; i < scripts.length; i++) {
  const script = scripts[i];
  const doc = sortedDocs[i] || null;

  items.push({
    json: {
      script_number: script.script_number,
      angle_name: script.angle_name,
      doc_content: script.doc_content,
      full_script: script.full_script,
      hook: script.hook,
      doc_id: doc ? doc.id : null,
      doc_name: doc ? doc.name : `No doc found for script ${script.script_number}`,
      brand_name: brief.brand_name,
      client_code: brief.client_code
    }
  });
}

if (items.length === 0) {
  return [{ json: { _skip: true, message: 'No scripts to write' } }];
}

return items;

// ============================================================
// Prepare for ClickUp Update
// Collapse loop output and prepare for ClickUp lookup
// ============================================================

const data = $('Parse & Format Scripts').first().json;
return [{ json: data }];

// ============================================================
// Find Brand Folder & Extract List ID
// Searches through ClickUp folders to find the brand's
// UGC folder and its pipeline list.
// ============================================================

const foldersData = $input.first().json;
const data = $('Prepare ClickUp Step').first().json;
const brief = data.brief;
const folderName = brief.brand_name + ' - UGC';

const folders = foldersData.folders || [];
const brandFolder = folders.find(f => f.name === folderName);

if (!brandFolder) {
  // Try partial match
  const partial = folders.find(f => f.name.toLowerCase().includes(brief.brand_name.toLowerCase()));
  if (!partial) {
    return [{ json: { folder_found: false, list_id: null, brand_name: brief.brand_name, message: 'Folder not found: ' + folderName } }];
  }
  // Use partial match
  const list = (partial.lists || []).find(l => l.name.includes('Pipeline') || l.name.includes('UGC'));
  return [{ json: { folder_found: true, folder_id: partial.id, list_id: list ? list.id : null, brand_name: brief.brand_name } }];
}

const lists = brandFolder.lists || [];
const pipelineList = lists.find(l => l.name.includes('Pipeline')) || lists[0];

return [{ json: { folder_found: true, folder_id: brandFolder.id, list_id: pipelineList ? pipelineList.id : null, brand_name: brief.brand_name } }];

// ============================================================
// Match Scripts to ClickUp Tasks
// Pairs AI scripts with UGC_C{N} tasks for description update
// ============================================================

const tasksData = $input.first().json;
const data = $('Parse & Format Scripts').first().json;
const scripts = data.scripts;

const tasks = tasksData.tasks || [];

// Find UGC script card tasks (match UGC_C pattern)
const scriptTasks = tasks.filter(t => /^UGC_C\d+/.test(t.name))
  .sort((a, b) => {
    const numA = parseInt((a.name.match(/UGC_C(\d+)/) || [0,0])[1]);
    const numB = parseInt((b.name.match(/UGC_C(\d+)/) || [0,0])[1]);
    return numA - numB;
  });

const items = [];
for (let i = 0; i < scripts.length; i++) {
  const script = scripts[i];
  const task = scriptTasks[i] || null;

  if (task) {
    const description = [
      `ANGLE: ${script.angle_name}`,
      `FORMAT: ${script.format}`,
      `DURATION: ${script.estimated_duration}`,
      '',
      '== FULL SCRIPT ==',
      script.full_script,
      '',
      '== HOOK ==',
      script.hook,
      '',
      '---',
      'AI-generated by Smashed Agency Script Agent',
      'Ready for review and creator briefing'
    ].join('\n');

    items.push({
      json: {
        task_id: task.id,
        task_name: task.name,
        description
      }
    });
  }
}

if (items.length === 0) {
  return [{ json: { _skip: true, message: 'No matching ClickUp tasks found' } }];
}

return items;

// ============================================================
// Prepare Notification Data
// Collapses loop output and prepares Slack + log data
// ============================================================

const data = $('Parse & Format Scripts').first().json;
const brief = data.brief;
const scripts = data.scripts;

const scriptSummary = scripts.map(s => 
  `  ${s.script_number}. "${s.angle_name}" (${s.format}) — Hook: "${s.hook.substring(0, 50)}..."`
).join('\n');

return [{
  json: {
    brand_name: brief.brand_name,
    client_code: brief.client_code,
    client_name: brief.client_name,
    client_email: brief.client_email,
    total_scripts: scripts.length,
    script_summary: scriptSummary,
    scripts: scripts
  }
}];

